1: /**
2:  * Pure usage summary builder.
3:  *
4:  * Stateless and independent of file I/O so it can be tested without a
5:  * tracker. The Usage Ledger is the source of truth; after each ledger
6:  * append the Usage Summary is recomputed from the full ledger.
7:  *
8:  * See ADR-0009.
9:  */
10: 
11: import type {
12:   AgentExecutionUsage,
13:   UsageLedgerEntry,
14:   UsageSummary,
15:   UsageTotals,
16:   PromptPhase,
17: } from "./state.js";
18: 
19: const TOKEN_FIELDS: Array<Exclude<keyof AgentExecutionUsage, "perModelUsage" | "totalTokens" | "costUsd" | "contextTokens" | "maxContext">> = [
20:   "inputTokens",
21:   "outputTokens",
22:   "cacheReadTokens",
23:   "cacheWriteTokens",
24:   "reasoningTokens",
25: ];
26: 
27: function zeroTotals(): UsageTotals {
28:   return {
29:     inputTokens: 0,
30:     outputTokens: 0,
31:     cacheReadTokens: 0,
32:     cacheWriteTokens: 0,
33:     reasoningTokens: 0,
34:     totalTokens: 0,
35:     costUsd: 0,
36:     hasUnknownTokens: false,
37:     hasUnknownCost: false,
38:   };
39: }
40: 
41: function accumulateInto(target: UsageTotals, entry: UsageLedgerEntry): void {
42:   for (const field of TOKEN_FIELDS) {
43:     const val = entry[field];
44:     if (val !== null) {
45:       target[field] += val;
46:     }
47:   }
48:   if (entry.totalTokens === null) {
49:     target.hasUnknownTokens = true;
50:   } else {
51:     target.totalTokens += entry.totalTokens;
52:   }
53:   if (entry.costUsd === null) {
54:     target.hasUnknownCost = true;
55:   } else {
56:     target.costUsd += entry.costUsd;
57:   }
58: }
59: 
60: /**
61:  * Recompute the full Usage Summary from the Usage Ledger.
62:  *
63:  * Aggregates known numeric values and sets `hasUnknownTokens` /
64:  * `hasUnknownCost` flags when any relevant field is `null`. Groups
65:  * totals by run, by issue, and by phase.
66:  */
67: export function buildUsageSummary(ledger: UsageLedgerEntry[]): UsageSummary {
68:   const run = zeroTotals();
69:   const byIssue: Record<string, UsageTotals> = {};
70:   const byPhase: Record<PromptPhase, UsageTotals> = {
71:     implement: zeroTotals(),
72:     verify: zeroTotals(),
73:     merger: zeroTotals(),
74:     review: zeroTotals(),
75:     // Live steering messages are recorded as prompt artifacts but do not generate
76:     // token-usage ledger entries. The key must exist for type completeness.
77:     "live-steering": zeroTotals(),
78:   };
79: 
80:   for (const entry of ledger) {
81:     accumulateInto(run, entry);
82: 
83:     if (entry.issueId != null) {
84:       const key = String(entry.issueId);
85:       if (!byIssue[key]) {
86:         byIssue[key] = zeroTotals();
87:       }
88:       accumulateInto(byIssue[key], entry);
89:     }
90: 
91:     accumulateInto(byPhase[entry.phase], entry);
92:   }
93: 
94:   return { run, byIssue, byPhase };
95: }
