52: describe("ControlledRunner sumUsage merge", () => {
53:   function addNullable(a: number | null, b: number | null): number | null {
54:     if (a === null && b === null) return null;
55:     return (a ?? 0) + (b ?? 0);
56:   }
57: 
58:   function mergePerModelUsage(
59:     existing: PerModelUsage[] | undefined,
60:     incoming: PerModelUsage[] | undefined,
61:   ): PerModelUsage[] | undefined {
62:     if (!existing && !incoming) return undefined;
63:     if (!existing) return [...incoming!];
64:     if (!incoming) return [...existing];
65:     const merged = new Map<string, PerModelUsage>();
66:     for (const entry of existing) {
67:       merged.set(entry.model, { ...entry });
68:     }
69:     for (const entry of incoming) {
70:       const prev = merged.get(entry.model);
71:       if (prev) {
72:         merged.set(entry.model, {
73:           model: entry.model,
74:           inputTokens: addNullable(prev.inputTokens, entry.inputTokens),
75:           outputTokens: addNullable(prev.outputTokens, entry.outputTokens),
76:           cacheReadTokens: addNullable(prev.cacheReadTokens, entry.cacheReadTokens),
77:           cacheWriteTokens: addNullable(prev.cacheWriteTokens, entry.cacheWriteTokens),
78:           reasoningTokens: addNullable(prev.reasoningTokens, entry.reasoningTokens),
79:           costUsd: addNullable(prev.costUsd, entry.costUsd),
80:         });
81:       } else {
82:         merged.set(entry.model, { ...entry });
83:       }
84:     }
85:     return [...merged.values()];
86:   }
87: 
88:   it("merges duplicate per-model rows by model", () => {
89:     const existing: PerModelUsage[] = [
90:       { model: "claude-sonnet-4-20250514", inputTokens: 60, outputTokens: 120, cacheReadTokens: null, cacheWriteTokens: null, costUsd: 0.006 },
91:       { model: "claude-haiku-3-20240307", inputTokens: 40, outputTokens: 80, cacheReadTokens: null, cacheWriteTokens: null, costUsd: 0.004 },
92:     ];
